import { buildScene } from '@game/engine/buildScene';
import { createInputLayer, type InputLayer } from './input';
private inputLayer: InputLayer | null = null;

import { phaserToReact } from './events';
export function handleMenuKey(key: string): boolean {
  if (key !== 'Escape') return false;
  phaserToReact.emit('menuClose', {});
  return true;
}

const releasers: Array<() => void> = [];
bindCharacter(target, id, onDown) {
  const fn = () => { if (!active) return; phaserToReact.emit('characterClick', { id }); onDown?.(); };
  target.on('pointerdown', fn);
  releasers.push(() => target.off('pointerdown', fn));
}
